contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // record owner and balance before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;
        // perform the call and record whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // read after-values
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;
        // If call didn't revert then all ether held by c after the call must be 0,
        // and owner must remain the same as before. If it reverted then we make no claim about balances.
        assert(reverted || (balanceAfter == 0 && ownerAfter == ownerBefore));
    }
    receive() external payable { }
}

